import { _decorator, Button, Prefab, ProgressBar, resources } from "cc";

const { ccclass, property } = _decorator;

@ccclass('Loading')
export class Loading extends Comment {

    @property(ProgressBar)
    progressBar: ProgressBar = null;

    @property(Button)
    joginGame: Button = null;

    private preloadList: string[] = [
        'prefab',
        'prefab/game',
        'prefab/gameEndScore',
        'prefab/gameEndScoreRank',
        'prefab/room'
    ];

    private totalSteps = 1;
    private finishedSteps = 0;

    start() {
        this.loadPrefabs().then(() => {
            // this.loadMainScene();
        });
    }

    private async loadPrefabs() {
        for (let path of this.preloadList) {
            await this.loadOnePrefab(path);
            this.finishedSteps++;
            this.updateProgress();
        }
    }

    private loadOnePrefab(path: string): Promise<void> {
        return new Promise((resolve) => {
            resources.load(path, Prefab, (err, prefab) => {
                if (err) {
                    console.warn(`加载失败: ${path}`, err);
                    resolve();
                    return;
                }
                // resources.add; // 选用：缓存资源
                resolve();
            });
        });
    }

     private updateProgress(p: number = this.finishedSteps / this.totalSteps) {
        this.progressBar.progress = p;
        // this.tipLabel.string = `初始化中 ${Math.floor(p * 100)}%`;
    }

}